#!/usr/bin/env bash
set -Eeuo pipefail;IFS=$'\n\t';umask 077
D="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")"&&pwd -P)";M="$D/model.py";F="$D/fixtures/cases.json";U="$(id -u)";R="/tmp/reliability-atlas-les0048-model-$U"
die(){ printf 'lab=fail reason=%s\n' "$*" >&2;exit 1;};doctor(){ ((U>0))||die root;grep -Eq '^ID="?ubuntu"?$' /etc/os-release||die ubuntu;grep -Eq '^VERSION_ID="?24\.04' /etc/os-release||die version;python3 -c 'import pathlib,sys;compile(pathlib.Path(sys.argv[1]).read_text(),sys.argv[1],"exec")' "$M";printf 'doctor=pass runtime=kubernetes-operations-model-only\n';};need(){ doctor>/dev/null;[[ -d "$R"&&! -L "$R" ]]||die state;python3 "$M" verify "$R">/dev/null;};setup(){ doctor;[[ ! -e "$R"&&! -L "$R" ]]||die exists;mkdir -m 0700 "$R";cp "$F" "$R/cases.json";printf 'les0048:%s\n' "$U">"$R/.les0048-sentinel";chmod 0600 "$R"/* "$R/.les0048-sentinel";python3 "$M" init "$R";};all(){ need;for c in unsupported-skew deprecated-api webhook-version drain-deadlock autoscaling-delay retry-overload invalid-snapshot incomplete-restore;do python3 "$M" diagnose "$R" "$c">/dev/null;done;python3 "$M" verify "$R";};cleanup(){ need;rm -rf -- "$R";[[ ! -e "$R" ]]||die remains;printf 'cleanup=pass state_absent=true\n';};clear_unknown(){ [[ "$R" == "/tmp/reliability-atlas-les0048-model-$U"&&-d "$R"&&! -L "$R"&&"$(stat -c %u "$R")" == "$U" ]]||die unsafe-clear;[[ -f "$R/unexpected"&&! -L "$R/unexpected" ]]||die unknown-shape;rm -f -- "$R/unexpected";need;};case "${1:-}" in doctor)doctor;;setup)setup;;list)need;python3 "$M" list "$R";;diagnose)need;python3 "$M" diagnose "$R" "${2:-}";;diagnose-as)need;python3 "$M" diagnose "$R" "${2:-}" --answer "${3:-}";;verify-cases)all;;inject-unknown)need;printf x>"$R/unexpected";;clear-unknown)clear_unknown;;cleanup)cleanup;;*)exit 2;;esac
